#include <string>
#include <vector>
#include "queue.h"

//==========================================
// GENRE TREE MODULE (HOA 9: general tree, traversals)
// Genres are organised like folders: "Action" has the children "Shooter" and "Platformer", and so on.
// A general tree node can have any number of children, so each node keeps
//   firstChild  : its first child
//   nextSibling : the next child of the same parent
// (the "left child, right sibling" representation).
// Every genre name is also a game tag, so a node can count the games that use it.
//
// Used by the "Browse by genre" screen in screens_discover.h.
//==========================================

struct GenreNode {
    std::string name;               // lowercase, same text as the game tag
    int gameCount = 0;              // games that carry this tag (filled by the caller)
    GenreNode* firstChild = nullptr;
    GenreNode* nextSibling = nullptr;
};

// a new node with no children
//--- genreCreate ----------------------------------------------------------------------------------
// What    : Creates one genre node without children.
// Returns : the new node
// Used by : genreAddChild, genreBuildDefault
//--------------------------------------------------------------------------------------------------
inline GenreNode* genreCreate(const std::string& name) {
    GenreNode* node = new GenreNode;
    node->name = name;
    return node;
}

// adds a child at the END of the parent's children, so the order of insertion is kept
//--- genreAddChild --------------------------------------------------------------------------------
// What    : Adds a child genre at the end of the parent's children, so the order of insertion is
//           kept.
// Returns : the new child node
// Used by : genreBuildDefault
//--------------------------------------------------------------------------------------------------
inline GenreNode* genreAddChild(GenreNode* parent, const std::string& name) {
    GenreNode* child = genreCreate(name);
    if (parent->firstChild == nullptr) {
        parent->firstChild = child;
    } else {
        GenreNode* last = parent->firstChild;
        while (last->nextSibling != nullptr) last = last->nextSibling;
        last->nextSibling = child;
    }
    return child;
}

// the node with this name anywhere under (and including) root, nullptr if none. Depth first.
//--- genreFind ------------------------------------------------------------------------------------
// What    : Depth first search for a genre by name in a tree.
// Returns : the node, or nullptr
// Used by : doGenres (screens.h)
//--------------------------------------------------------------------------------------------------
inline GenreNode* genreFind(GenreNode* root, const std::string& name) {
    if (root == nullptr) return nullptr;
    if (root->name == name) return root;
    GenreNode* found = genreFind(root->firstChild, name);
    if (found != nullptr) return found;
    return genreFind(root->nextSibling, name);
}

// the standard Store genres
//--- genreBuildDefault ----------------------------------------------------------------------------
// What    : Builds the standard genre tree of the store (action, adventure, rpg, strategy,
//           simulation, co-op, indie and their subgenres).
// Returns : the root node
// Used by : doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline GenreNode* genreBuildDefault() {
    GenreNode* root = genreCreate("all games");
    GenreNode* action = genreAddChild(root, "action");
    genreAddChild(action, "shooter");
    genreAddChild(action, "platformer");
    genreAddChild(action, "fighting");
    GenreNode* adventure = genreAddChild(root, "adventure");
    genreAddChild(adventure, "puzzle");
    genreAddChild(adventure, "story");
    GenreNode* rpg = genreAddChild(root, "rpg");
    genreAddChild(rpg, "roguelike");
    genreAddChild(rpg, "turn-based");
    GenreNode* strategy = genreAddChild(root, "strategy");
    genreAddChild(strategy, "tower-defense");
    genreAddChild(strategy, "city-builder");
    GenreNode* sim = genreAddChild(root, "simulation");
    genreAddChild(sim, "farming");
    genreAddChild(sim, "racing");
    genreAddChild(root, "co-op");
    genreAddChild(root, "indie");
    return root;
}

// how many nodes the tree has
//--- genreCount -----------------------------------------------------------------------------------
// What    : Counts the nodes of a tree.
// Returns : the number of genres
// Used by : doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline int genreCount(const GenreNode* node) {
    if (node == nullptr) return 0;
    return 1 + genreCount(node->firstChild) + genreCount(node->nextSibling);
}

// height of the tree, a lone root has height 1
//--- genreHeight ----------------------------------------------------------------------------------
// What    : Height of the tree. A lone root has height 1.
// Returns : the height
// Used by : doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline int genreHeight(const GenreNode* root) {
    if (root == nullptr) return 0;
    int tallest = 0;
    for (const GenreNode* c = root->firstChild; c != nullptr; c = c->nextSibling) {
        int h = genreHeight(c);
        if (h > tallest) tallest = h;
    }
    return 1 + tallest;
}

// Preorder: the parent first, then each child's subtree. Gives the tree as an outline.
// depth is stored next to the node so the screen can indent it.
struct GenreVisit {
    GenreNode* node = nullptr;
    int depth = 0;
};

//--- genrePreorder --------------------------------------------------------------------------------
// What    : Preorder traversal: the parent first, then each child's subtree. Gives the tree as an
//           indented outline.
// Used by : countGenreGames (screens.h), doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline void genrePreorder(GenreNode* node, int depth, std::vector<GenreVisit>& out) {
    if (node == nullptr) return;
    out.push_back(GenreVisit{node, depth});
    for (GenreNode* c = node->firstChild; c != nullptr; c = c->nextSibling) genrePreorder(c, depth + 1, out);
}

// Postorder: each child's subtree first, then the parent. A parent is visited after all of its children,
// which is the order needed to add the children's totals into the parent.
//--- genrePostorder -------------------------------------------------------------------------------
// What    : Postorder traversal: every child's subtree first, then the parent.
// Used by : doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline void genrePostorder(GenreNode* node, int depth, std::vector<GenreVisit>& out) {
    if (node == nullptr) return;
    for (GenreNode* c = node->firstChild; c != nullptr; c = c->nextSibling) genrePostorder(c, depth + 1, out);
    out.push_back(GenreVisit{node, depth});
}

// Level order: all nodes of depth 0, then depth 1, and so on. Uses a queue (same idea as BFS).
//--- genreLevelOrder ------------------------------------------------------------------------------
// What    : Level order traversal with a queue: all nodes of depth 0, then depth 1, and so on.
// Used by : doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline void genreLevelOrder(GenreNode* root, std::vector<GenreVisit>& out) {
    if (root == nullptr) return;
    LinkedQueue<GenreVisit> line;
    line.enqueue(GenreVisit{root, 0});
    GenreVisit cur;
    while (line.dequeue(cur)) {
        out.push_back(cur);
        for (GenreNode* c = cur.node->firstChild; c != nullptr; c = c->nextSibling) {
            line.enqueue(GenreVisit{c, cur.depth + 1});
        }
    }
}

// total games of a node = its own games + the games of every genre below it (postorder idea).
// The games of a subgenre are counted for the parent too, so "action" includes "shooter".
// A game that has two tags in the same branch is counted once for each tag. This is an overview, not a unique count.
//--- genreTotal -----------------------------------------------------------------------------------
// What    : Games of a genre plus the games of all its subgenres.
// Returns : the total
// Used by : doGenres (screens.h)
//--------------------------------------------------------------------------------------------------
inline int genreTotal(const GenreNode* node) {
    if (node == nullptr) return 0;
    int total = node->gameCount;
    for (const GenreNode* c = node->firstChild; c != nullptr; c = c->nextSibling) total += genreTotal(c);
    return total;
}

// the path of names from the root down to the node with this name ("all games > action > shooter")
//--- genrePath ------------------------------------------------------------------------------------
// What    : Finds the path of names from the root down to a genre.
// Returns : true when the genre exists
// Used by : doGenres (screens.h)
//--------------------------------------------------------------------------------------------------
inline bool genrePath(const GenreNode* node, const std::string& name, std::vector<std::string>& path) {
    if (node == nullptr) return false;
    path.push_back(node->name);
    if (node->name == name) return true;
    for (const GenreNode* c = node->firstChild; c != nullptr; c = c->nextSibling) {
        if (genrePath(c, name, path)) return true;
    }
    path.pop_back();
    return false;
}

// every name in the subtree (used to filter the catalog by "action" and all of its subgenres)
//--- genreNamesUnder ------------------------------------------------------------------------------
// What    : Collects the names of a genre and all genres below it, to filter games by a whole
//           branch.
// Used by : doGenres (screens.h)
//--------------------------------------------------------------------------------------------------
inline void genreNamesUnder(const GenreNode* node, std::vector<std::string>& out) {
    if (node == nullptr) return;
    out.push_back(node->name);
    for (const GenreNode* c = node->firstChild; c != nullptr; c = c->nextSibling) genreNamesUnder(c, out);
}

// frees the whole tree (children first)
//--- genreFree ------------------------------------------------------------------------------------
// What    : Frees the whole tree, children first.
// Used by : doGenres (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline void genreFree(GenreNode* node) {
    if (node == nullptr) return;
    genreFree(node->firstChild);
    genreFree(node->nextSibling);
    delete node;
}

#endif //STEAM_GENRE_H
